const p = await browser.open('https://play.google.com/store/apps/details?id=com.cha0smagicklabs.astralchart&hl=es&gl=US');
await sleep(7000);
const raw = await p.evaluate(() => { try {
  const body = String((document.body && document.body.textContent) || '').replace(/\s+/g, ' ');
  const btns = Array.from(document.querySelectorAll('button, a, [role=button]')).map(b => String(b.innerText || b.getAttribute('aria-label') || '').replace(/\s+/g, ' ').trim()).filter(t => /comprar|buy|instalar|install|\$|US\$|gratis|free|ver en|open/i.test(t)).slice(0, 8);
  const ld = Array.from(document.querySelectorAll('script[type="application/ld+json"]')).map(s => { try { return JSON.parse(s.textContent) } catch { return null } }).filter(Boolean);
  const meta = document.querySelector('meta[property="product:price:amount"]')?.content || document.querySelector('meta[itemprop="price"]')?.content || null;
  const cur = document.querySelector('meta[property="product:price:currency"]')?.content || null;
  return { title: document.title.slice(0, 70), h1: (document.querySelector('h1')||{}).innerText || null, priceMeta: meta, curMeta: cur, btns, ldRaw: JSON.stringify(ld).slice(0, 500), bodyHead: body.slice(0, 420), notFound: /Item not found|We're sorry/i.test(body.slice(0, 400)) };
} catch (e) { return { err: String(e.message).slice(0, 80) } } });
console.log('ASTRAL ' + JSON.stringify(raw));
